std::uint64_t hashFence(const MRNumanXHumanMatterJointPublicationFenceGPU& f){
    const auto* p=reinterpret_cast<const std::uint8_t*>(&f);std::uint64_t h=14695981039346656037ull;
    for(unsigned i=0;i<120;++i){h^=p[i];h*=1099511628211ull;}return h;
}
std::uint64_t hashTraceRecord(const mrnx_behavior_trace_record_v1& r){
    const auto* p=reinterpret_cast<const std::uint8_t*>(&r);std::uint64_t h=14695981039346656037ull;
    for(std::size_t i=0;i<offsetof(mrnx_behavior_trace_record_v1,record_fingerprint);++i){h^=p[i];h*=1099511628211ull;}return h;
}
std::array<std::uint8_t,32> hashStateComponentRecord(
    const mrnx_behavior_trace_state_component_record_v1& r){
