    mrnx_behavior_trace_state_component_bundle_v1 stateComponents(
        const MRHumanBehaviorReleaseGPU& r,bool accepted,std::uint8_t seed,
        std::uint32_t coverage=MRNX_BEHAVIOR_TRACE_STATE_COMPONENT_COMPLETE_MASK_V1){
